$gameActors.actor(acotorId).gainSkillAP(skillId, ap)
For the Entire Party to gain AP you can throw this functtion att tthe  bottom of the equipment  skills plugin:
Spoiler:
gainPartyAP Function
Game_Party.prototype.gainPartyAP = function(ap) {
for (const actor of this.members()) {
if (actor && actor.isActor()) {
actor.gainAP(ap);
}
}
};
Then  call
$gameParty.gainPartyAP(x);
using whattever  number  in place of x
For the same thing but with a specific  skill:
Spoiler:
gainPartySkillAP Function
Game_Party.prototype.gainPartySkillAP = function(skillId, ap) {
for (const actor of this.members()) {
if (actor && actor.isActor()) {
actor.gainSkillAP(skillId, ap);
}
}
};
Then  call
$gameParty.gainPartySkillAP (x, y)
; using whatever  your skill id to replace x and tthe amount of ap for y
